-- Offline games: a cover with Chike and friends, a picture for every rule (small, plus a large copy for the
-- enlarged view) and a printable each; and printables for the three activities that had none.
-- Run AFTER assets/games/offline/ and the new assets/printables/*.pdf are live. Safe to re-run.

begin;
update games set data = data || '{"cover": {"src": "assets/games/offline/bridge-challenge.jpg", "alt": "Mateo sets a coin on a paper bridge between two stacks of books while Chike watches, ready to catch it"}, "rulePictures": [{"src": "assets/games/offline/bridge-challenge/rule-1.jpg", "full": "assets/games/offline/bridge-challenge/rule-1-large.jpg", "alt": "Mateo and Chike each hold up one sheet of paper, with the tape pushed away"}, {"src": "assets/games/offline/bridge-challenge/rule-2.jpg", "full": "assets/games/offline/bridge-challenge/rule-2-large.jpg", "alt": "Mateo peeks under a folded paper bridge that spans the gap between two stacks of books"}, {"src": "assets/games/offline/bridge-challenge/rule-3.jpg", "full": "assets/games/offline/bridge-challenge/rule-3-large.jpg", "alt": "The paper bridge collapses under the coins and both boys laugh"}, {"src": "assets/games/offline/bridge-challenge/rule-4.jpg", "full": "assets/games/offline/bridge-challenge/rule-4-large.jpg", "alt": "Mateo folds a fresh sheet into tight zigzag pleats for his second bridge"}], "printable": {"path": "assets/printables/bridge-load-log.pdf", "label": "Bridge load log"}}'::jsonb where id = 'game-bridge-challenge' and jsonb_array_length(data->'rules') = 4;
update games set data = data || '{"cover": {"src": "assets/games/offline/draw-what-i-say.jpg", "alt": "Kiyah describes a secret picture of a house while Yuna draws it on a clipboard"}, "rulePictures": [{"src": "assets/games/offline/draw-what-i-say/rule-1.jpg", "full": "assets/games/offline/draw-what-i-say/rule-1-large.jpg", "alt": "Kiyah hides a secret picture card and presses a finger to her lips"}, {"src": "assets/games/offline/draw-what-i-say/rule-2.jpg", "full": "assets/games/offline/draw-what-i-say/rule-2-large.jpg", "alt": "Kiyah shapes a circle in the air with her hands while Yuna draws it"}, {"src": "assets/games/offline/draw-what-i-say/rule-3.jpg", "full": "assets/games/offline/draw-what-i-say/rule-3-large.jpg", "alt": "A folder stands between the girls like a wall so Yuna cannot peek"}, {"src": "assets/games/offline/draw-what-i-say/rule-4.jpg", "full": "assets/games/offline/draw-what-i-say/rule-4-large.jpg", "alt": "The girls hold up the original cat and Yuna''s funny version side by side and laugh"}], "printable": {"path": "assets/printables/draw-what-i-say-cards.pdf", "label": "Picture cards"}}'::jsonb where id = 'game-draw-what-i-say' and jsonb_array_length(data->'rules') = 4;
update games set data = data || '{"cover": {"src": "assets/games/offline/freeze-and-swap.jpg", "alt": "Averi freezes as a tree on one foot and Zech freezes as a frog when the music stops"}, "rulePictures": [{"src": "assets/games/offline/freeze-and-swap/rule-1.jpg", "full": "assets/games/offline/freeze-and-swap/rule-1-large.jpg", "alt": "Averi and Zech dance while music plays from a speaker"}, {"src": "assets/games/offline/freeze-and-swap/rule-2.jpg", "full": "assets/games/offline/freeze-and-swap/rule-2-large.jpg", "alt": "Yuna calls out a word and Zech freezes as a rocket"}, {"src": "assets/games/offline/freeze-and-swap/rule-3.jpg", "full": "assets/games/offline/freeze-and-swap/rule-3-large.jpg", "alt": "Averi and Zech balance on one foot like flamingos, Zech wobbling"}, {"src": "assets/games/offline/freeze-and-swap/rule-4.jpg", "full": "assets/games/offline/freeze-and-swap/rule-4-large.jpg", "alt": "Zech takes a turn as the caller while Averi and Yuna freeze as cats"}], "printable": {"path": "assets/printables/freeze-and-swap-call-cards.pdf", "label": "Call cards"}}'::jsonb where id = 'game-freeze-swap' and jsonb_array_length(data->'rules') = 4;
update games set data = data || '{"cover": {"src": "assets/games/offline/materials-mashup.jpg", "alt": "Chike and Corey hold up the inventions they built from a pile of everyday objects"}, "rulePictures": [{"src": "assets/games/offline/materials-mashup/rule-1.jpg", "full": "assets/games/offline/materials-mashup/rule-1-large.jpg", "alt": "Corey hurries across the playroom with a sock and a wooden spoon while a timer ticks"}, {"src": "assets/games/offline/materials-mashup/rule-2.jpg", "full": "assets/games/offline/materials-mashup/rule-2-large.jpg", "alt": "Chike and Corey drop their objects into one pile on the rug"}, {"src": "assets/games/offline/materials-mashup/rule-3.jpg", "full": "assets/games/offline/materials-mashup/rule-3-large.jpg", "alt": "Chike chooses a paper tube and clothespins from the pile"}, {"src": "assets/games/offline/materials-mashup/rule-4.jpg", "full": "assets/games/offline/materials-mashup/rule-4-large.jpg", "alt": "Chike shows his paper-tube telescope while Corey listens"}], "printable": {"path": "assets/printables/materials-mashup-cards.pdf", "label": "Challenge cards"}}'::jsonb where id = 'game-materials-mashup' and jsonb_array_length(data->'rules') = 4;
update games set data = data || '{"cover": {"src": "assets/games/offline/sound-scavenger-hunt.jpg", "alt": "Stacey tiptoes across the backyard with a hand behind her ear and a checklist, listening for sounds"}, "rulePictures": [{"src": "assets/games/offline/sound-scavenger-hunt/rule-1.jpg", "full": "assets/games/offline/sound-scavenger-hunt/rule-1-large.jpg", "alt": "Stacey listens in the backyard to a high bird chirp and a low dog bark"}, {"src": "assets/games/offline/sound-scavenger-hunt/rule-2.jpg", "full": "assets/games/offline/sound-scavenger-hunt/rule-2-large.jpg", "alt": "Stacey hums and draws the bird she heard on her clipboard"}, {"src": "assets/games/offline/sound-scavenger-hunt/rule-3.jpg", "full": "assets/games/offline/sound-scavenger-hunt/rule-3-large.jpg", "alt": "Stacey shakes her head at the wind chime she already found"}, {"src": "assets/games/offline/sound-scavenger-hunt/rule-4.jpg", "full": "assets/games/offline/sound-scavenger-hunt/rule-4-large.jpg", "alt": "Stacey shows Kiyah her rarest find, an owl hooting in the tree"}], "printable": {"path": "assets/printables/sound-hunt-checklist.pdf", "label": "Sound hunt checklist"}}'::jsonb where id = 'game-sound-hunt' and jsonb_array_length(data->'rules') = 4;
update games set data = data || '{"cover": {"src": "assets/games/offline/story-relay.jpg", "alt": "Zech, Corey and Yuna tell a story in a circle while a dragon rides a bicycle in the story cloud above them"}, "rulePictures": [{"src": "assets/games/offline/story-relay/rule-1.jpg", "full": "assets/games/offline/story-relay/rule-1-large.jpg", "alt": "Corey holds up one finger as he adds his one sentence"}, {"src": "assets/games/offline/story-relay/rule-2.jpg", "full": "assets/games/offline/story-relay/rule-2-large.jpg", "alt": "Yuna adds to Zech''s spaghetti dragon instead of undoing it"}, {"src": "assets/games/offline/story-relay/rule-3.jpg", "full": "assets/games/offline/story-relay/rule-3-large.jpg", "alt": "Zech gasps at a kitten stuck in a tree and Corey brings a ladder to solve it"}, {"src": "assets/games/offline/story-relay/rule-4.jpg", "full": "assets/games/offline/story-relay/rule-4-large.jpg", "alt": "Zech, Corey and Yuna write the ending together in one notebook"}], "printable": {"path": "assets/printables/story-relay-starters.pdf", "label": "Story-starter cards"}}'::jsonb where id = 'game-story-relay' and jsonb_array_length(data->'rules') = 4;
update activities set data = jsonb_set(data, '{printable}', '{"path": "assets/printables/volcano-eruption-log.pdf", "label": "Volcano eruption log"}'::jsonb) where id = 'act-clay-volcano' and coalesce(data->'printable'->>'path', '') = '';
update activities set data = jsonb_set(data, '{printable}', '{"path": "assets/printables/line-dance-step-chart.pdf", "label": "Line-dance step chart"}'::jsonb) where id = 'act-line-dance' and coalesce(data->'printable'->>'path', '') = '';
update activities set data = jsonb_set(data, '{printable}', '{"path": "assets/printables/neighborhood-map-maker.pdf", "label": "Map-maker sheet"}'::jsonb) where id = 'act-neighborhood-map' and coalesce(data->'printable'->>'path', '') = '';
commit;
